18	
19	import com.google.zxing.BarcodeFormat;
20	import com.google.zxing.FormatException;
21	import com.google.zxing.common.BitMatrix;
22	
23	import java.util.Collection;
24	import java.util.Collections;
25	
26	/**
27	 * This object renders an EAN13 code as a {@link BitMatrix}.
28	 *
29	 * @author aripollak@gmail.com (Ari Pollak)
30	 */
31	public final class EAN13Writer extends UPCEANWriter {
32	
33	  private static final int CODE_WIDTH = 3 + // start guard
34	      (7 * 6) + // left bars
35	      5 + // middle guard
36	      (7 * 6) + // right bars
37	      3; // end guard
38	
39	  @Override
40	  protected Collection<BarcodeFormat> getSupportedWriteFormats() {
41	    return Collections.singleton(BarcodeFormat.EAN_13);
42	  }
43	
44	  @Override
45	  public boolean[] encode(String contents) {
46	    int length = contents.length();
47	    switch (length) {
48	      case 12:
49	        // No check digit present, calculate it and add it
50	        int check;
51	        try {
52	          check = UPCEANReader.getStandardUPCEANChecksum(contents);
53	        } catch (FormatException fe) {
54	          throw new IllegalArgumentException(fe);
55	        }
56	        contents += check;
57	        break;
58	      case 13:
59	        try {
60	          if (!UPCEANReader.checkStandardUPCEANChecksum(contents)) {
61	            throw new IllegalArgumentException("Contents do not pass checksum");
62	          }
63	        } catch (FormatException ignored) {
64	          throw new IllegalArgumentException("Illegal contents");
65	        }
66	        break;
67	      default:
68	        throw new IllegalArgumentException(
69	            "Requested contents should be 12 or 13 digits long, but got " + length);
70	    }
71	
72	    checkNumeric(contents);
73	
74	    int firstDigit = Character.digit(contents.charAt(0), 10);
75	    int parities = EAN13Reader.FIRST_DIGIT_ENCODINGS[firstDigit];
76	    boolean[] result = new boolean[CODE_WIDTH];
77	    int pos = 0;
78	
79	    pos += appendPattern(result, pos, UPCEANReader.START_END_PATTERN, true);
80	
81	    // See EAN13Reader for a description of how the first digit & left bars are encoded
82	    for (int i = 1; i <= 6; i++) {
83	      int digit = Character.digit(contents.charAt(i), 10);
84	      if ((parities >> (6 - i) & 1) == 1) {
85	        digit += 10;
86	      }
87	      pos += appendPattern(result, pos, UPCEANReader.L_AND_G_PATTERNS[digit], false);
88	    }
89	
90	    pos += appendPattern(result, pos, UPCEANReader.MIDDLE_PATTERN, false);
91	
92	    for (int i = 7; i <= 12; i++) {
93	      int digit = Character.digit(contents.charAt(i), 10);
94	      pos += appendPattern(result, pos, UPCEANReader.L_PATTERNS[digit], true);
95	    }
96	    appendPattern(result, pos, UPCEANReader.START_END_PATTERN, true);
97	
98	    return result;
99	  }
100	
101	}
