48	  public boolean[] encode(String contents) {
49	    int length = contents.length();
50	    switch (length) {
51	      case 7:
52	        // No check digit present, calculate it and add it
53	        int check;
54	        try {
55	          check = UPCEANReader.getStandardUPCEANChecksum(contents);
56	        } catch (FormatException fe) {
57	          throw new IllegalArgumentException(fe);
58	        }
59	        contents += check;
60	        break;
61	      case 8:
62	        try {
63	          if (!UPCEANReader.checkStandardUPCEANChecksum(contents)) {
64	            throw new IllegalArgumentException("Contents do not pass checksum");
65	          }
66	        } catch (FormatException ignored) {
67	          throw new IllegalArgumentException("Illegal contents");
68	        }
69	        break;
70	      default:
71	        throw new IllegalArgumentException(
72	            "Requested contents should be 7 or 8 digits long, but got " + length);
73	    }
74	
75	    checkNumeric(contents);
76	
77	    boolean[] result = new boolean[CODE_WIDTH];
78	    int pos = 0;
79	
80	    pos += appendPattern(result, pos, UPCEANReader.START_END_PATTERN, true);
81	
82	    for (int i = 0; i <= 3; i++) {
83	      int digit = Character.digit(contents.charAt(i), 10);
