23	/**
24	 * Implements the "MATMSG" email message entry format.
25	 *
26	 * Supported keys: TO, SUB, BODY
27	 *
28	 * @author Sean Owen
29	 */
30	public final class EmailDoCoMoResultParser extends AbstractDoCoMoResultParser {
31	
32	  private static final String EMAIL_LOCAL = "[^:]+";
33	  private static final String EMAIL_DOMAIN = "([0-9a-zA-Z]+(-+[0-9a-zA-Z]+)*\\.)+[a-zA-Z]{2,}";
34	  private static final Pattern EMAIL = Pattern.compile("^" + EMAIL_LOCAL + "@" + EMAIL_DOMAIN + "$");
35	  
36	  @Override
37	  public EmailAddressParsedResult parse(Result result) {
38	    String rawText = getMassagedText(result);
39	    if (!rawText.startsWith("MATMSG:")) {
40	      return null;
41	    }
42	    String[] tos = matchDoCoMoPrefixedField("TO:", rawText);
43	    if (tos == null) {
44	      return null;
45	    }
46	    for (String to : tos) {
47	      if (!isBasicallyValidEmailAddress(to)) {
48	        return null;
49	      }
50	    }
51	    String subject = matchSingleDoCoMoPrefixedField("SUB:", rawText, false);
52	    String body = matchSingleDoCoMoPrefixedField("BODY:", rawText, false);
53	    return new EmailAddressParsedResult(tos, null, null, subject, body);
54	  }
55	
56	  /**
