import java.io.File;
import java.lang.reflect.Method;
import java.net.URL;
import java.net.URLClassLoader;
import java.util.ArrayList;
import java.util.List;
import java.util.Random;

/** Differential test: compares encode(String) output of the original vs refactored UPC/EAN writers. */
public final class DiffTest {

  static URLClassLoader loader(String dir) throws Exception {
    return new URLClassLoader(new URL[]{ new File(dir).toURI().toURL() }, null);
  }

  /** Returns either "OK:<bits>" or "EX:<exceptionClass>:<message>" for one encode call. */
  static String run(ClassLoader cl, String className, String contents) {
    try {
      Class<?> c = Class.forName("com.google.zxing.oned." + className, true, cl);
      Object inst = c.getDeclaredConstructor().newInstance();
      Method m = c.getMethod("encode", String.class);
      boolean[] out = (boolean[]) m.invoke(inst, contents);
      StringBuilder sb = new StringBuilder("OK:");
      for (boolean b : out) {
        sb.append(b ? '1' : '0');
      }
      return sb.toString();
    } catch (Throwable t) {
      // Unwrap InvocationTargetException to the real cause
      Throwable cause = (t.getCause() != null) ? t.getCause() : t;
      return "EX:" + cause.getClass().getName() + ":" + cause.getMessage();
    }
  }

  public static void main(String[] args) throws Exception {
    ClassLoader oldCl = loader(args[0]);
    ClassLoader newCl = loader(args[1]);

    List<String> inputs = new ArrayList<>();
    // Fixed edge cases
    String[] fixed = {
        "", "1", "abc", "12345", "123456", "1234567", "12345678",
        "123456789012", "1234567890123", "12345678901234",
        "00000000000", "000000000000", "0000000000000",
        "5901234123457", "590123412345", "5901234123450",
        "96385074", "9638507", "0123456", "01234565", "01234560",
        "1234567a", "12345a7", "123456789o12", "0000000", "00000000",
        " 1234567", "1234567 ",
    };
    for (String s : fixed) {
      inputs.add(s);
    }
    // Random numeric strings of lengths 5..14
    Random r = new Random(42);
    for (int len = 5; len <= 14; len++) {
      for (int k = 0; k < 400; k++) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < len; i++) {
          sb.append((char) ('0' + r.nextInt(10)));
        }
        inputs.add(sb.toString());
      }
    }

    String[] writers = { "EAN13Writer", "EAN8Writer", "UPCEWriter" };
    int total = 0;
    int mismatches = 0;
    for (String w : writers) {
      for (String in : inputs) {
        total++;
        String a = run(oldCl, w, in);
        String b = run(newCl, w, in);
        if (!a.equals(b)) {
          mismatches++;
          if (mismatches <= 30) {
            System.out.println("MISMATCH " + w + " input=[" + in + "]");
            System.out.println("   old: " + a);
            System.out.println("   new: " + b);
          }
        }
      }
    }
    System.out.println("----");
    System.out.println("Total comparisons: " + total);
    System.out.println("Mismatches:        " + mismatches);
    System.out.println(mismatches == 0 ? "RESULT: IDENTICAL BEHAVIOR" : "RESULT: DIFFERENCES FOUND");
  }
}

